import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
import { ResourcePatternTypes } from "../enumerations.js";
/* DescribeAcls Request (Version: 0) => resource_type_filter resource_name_filter principal_filter host_filter operation permission_type
   resource_type_filter => INT8; resource_name_filter, principal_filter, host_filter => NULLABLE_STRING; operation, permission_type => INT8 */
export function createRequest(filter) {
    return Writer.create().appendInt8(filter.resourceType).appendString(filter.resourceName, false).appendString(filter.principal, false)
        .appendString(filter.host, false).appendInt8(filter.operation).appendInt8(filter.permissionType);
}
/* DescribeAcls Response (Version: 0) => throttle_time_ms error_code error_message [resources]
   resources => resource_type resource_name [acls]; acls => principal host operation permission_type */
export function parseResponse(_, apiKey, apiVersion, reader) {
    const response = { throttleTimeMs: reader.readInt32(), errorCode: reader.readInt16(), errorMessage: reader.readNullableString(false), resources: reader.readArray(r => ({ resourceType: r.readInt8(), resourceName: r.readString(false), resourcePatternType: ResourcePatternTypes.LITERAL, acls: r.readArray(r => ({ principal: r.readString(false), host: r.readString(false), operation: r.readInt8(), permissionType: r.readInt8() }), false, false) }), false, false) };
    if (response.errorCode)
        throw new ResponseError(apiKey, apiVersion, { '/': [response.errorCode, response.errorMessage] }, response);
    return response;
}
export const api = createAPI(29, 0, createRequest, parseResponse, false, false);
